function localISODate(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,"0"),day=String(d.getDate()).padStart(2,"0");return y+"-"+m+"-"+day}function gameTeams(g){const home=g.homeTeam||g.home_team||g.home||g.teams?.home||{},away=g.awayTeam||g.away_team||g.away||g.teams?.away||{};const val=t=>typeof t==="string"?t:(t?.abbreviation||t?.shortName||t?.name||t?.displayName||t?.code||"");return [val(away),val(home)].filter(Boolean)}function gameDate(g,fallback){const raw=g.date||g.startDate||g.start_time||g.startTime||g.timestamp;const d=raw?new Date(raw):null;return d&&!isNaN(d)?localISODate(d):fallback}async function loadSleeperPlayers(){if(state.sleeperPlayers)return state.sleeperPlayers;const r=await fetch(API+"/players/nba");if(!r.ok)throw Error("Sleeper players "+r.status);state.sleeperPlayers=await r.json();return state.sleeperPlayers}function nbaTeamKey(v){return String(v||"").trim().toUpperCase().replace(/[^A-Z0-9]/g,"")}const nbaIds={ATL:1610612737,BOS:1610612738,BKN:1610612751,CHA:1610612766,CHI:1610612741,CLE:1610612739,DAL:1610612742,DEN:1610612743,DET:1610612765,GSW:1610612744,HOU:1610612745,IND:1610612754,LAC:1610612746,LAL:1610612747,MEM:1610612763,MIA:1610612748,MIL:1610612749,MIN:1610612750,NOP:1610612740,NYK:1610612752,OKC:1610612760,ORL:1610612753,PHI:1610612755,PHX:1610612756,POR:1610612757,SAC:1610612758,SAS:1610612759,TOR:1610612761,UTA:1610612762,WAS:1610612764};
let logoMode="retro";try{logoMode=localStorage.getItem("lf-logo-mode")==="modern"?"modern":"retro"}catch{}
function logoCode(s){const k=nbaTeamKey(s);return ({GS:"GSW",NO:"NOP",NY:"NYK",SA:"SAS",PHO:"PHX",BK:"BKN",WSH:"WAS",UT:"UTA",UTH:"UTA",UTAH:"UTA",JAZZ:"UTA",LONDONLIONS:"LON"})[k]||k}
function nbaLogo(s){const k=logoCode(s),id=nbaIds[k];if(logoMode==="retro")return '<span class="nba-retro-badge">'+esc(k)+'</span>';return id?'<img loading="lazy" class="nba-team-logo" src="https://cdn.nba.com/logos/nba/'+id+'/global/L/logo.svg" alt="'+esc(k)+' logo" onerror="this.onerror=null;this.src=\'https://cdn.nba.com/logos/nba/'+id+'/primary/L/logo.svg\';this.onerror=function(){this.replaceWith(document.createTextNode(\''+esc(k)+'\'))}">':'<span class="nba-retro-badge">'+esc(k)+'</span>'}
